helper_mismatch_title: "PS5 ヘルパーは v{payload}、このアプリは v{app} です",
helper_mismatch_send: "ヘルパーを送る",
helper_mismatch_body_v3: "PS5 側で行うことはありません。「ヘルパーを送る」を押すと、このアプリが本体に合ったヘルパーを送ります。それまでは新しいバージョンの修正や機能は動作しません。",

"joberr.direct_staged_file_missing": "このアップロードはすでに完了していたため、公開するものが残っていません。さらに PS5 上のファイルが見つからないか、サイズが正しくありません。もう一度アップロードし、「再開」ではなく「上書き」を選んでください。",
"joberr.direct_tx_corrupt": "この転送で PS5 がプロトコルの破損を検出しました。「ペイロード送信」タブからペイロードを再起動して、もう一度お試しください。",
"joberr.direct_writer_io_error": "ファイルの書き込み中に PS5 の空き容量がなくなりました（または外付けドライブが取り外されました）。転送先ドライブの空き容量を確保して「再試行」をクリックしてください。アップロードは中断した位置から再開されます。",
"joberr.fs_delete_path_not_allowed": "PS5 がそのパスへのアクセスを拒否しました。/data/、/user/、またはマウント済みの /mnt/ext*、/mnt/usb* のパスを使用してください。",
"joberr.fs_read_path_not_allowed": "このファイルは通常ブロックされている読み取り専用のシステムパーティションにあります。設定の「システムファイルのダウンロードを許可」を有効にすると、/system や /system_data などの保護されたパスからダウンロードできます。",
"joberr.fs_write_failed": "転送の途中で PS5 が転送先に書き込めませんでした。多くの場合、ドライブが満杯になったか、外付けドライブが取り外されています。空き容量を確認するかドライブを接続し直してから「再試行」をクリックしてください（アップロードは中断した位置から再開されます）。",
"joberr.fs_write_failed_no_space": "転送先ドライブの空き容量がなくなりました（またはファイルがそのファイルシステムには大きすぎます）。PS5 または外付けドライブの空き容量を確保するか、別の転送先を選んでから「再試行」をクリックしてください。",
"joberr.packed_unsupported": "PS5 ヘルパーがパック転送を拒否しました。これは、フォルダーのアップロードが小さなファイル 1 つだけになった場合（多数の小さなファイルを含むゲームの再開など）に、古いペイロードで発生します。ps5upload を最新版に更新し、「ペイロード送信」タブからペイロードを送り直してから、もう一度お試しください。",
"joberr.preflight_insufficient_space": "転送先ドライブにこのファイル用の空き容量が足りません。PS5 の空き容量を確保する（設定 → ストレージ）か、別の転送先を選んでから「再試行」をクリックしてください。",
"joberr.size_mismatch": "転送が完了する前に中断されました。PS5 上のファイルが不完全なため公開されていません（既存のコピーがある場合はそのまま残っています）。通常は、アップロード中に PS5 がレストモードに入ったか電源が切れたことを意味します。本体がスリープしないようにして（設定 → システム → 省電力 → PS5 の電源が切れるまでの時間）、この項目をもう一度実行してください。「再開」は不足しているファイルのみを送り直し、「上書き」はきれいなコピーを作成します。",
"joberr.ava1_stalled": "転送の進行が止まりました(転送元がデータを送らなくなりました)。再試行してください。繰り返す場合は、転送元のドライブまたはネットワーク共有を確認してください。",
"joberr.tx_table_full": "PS5 で同時に実行中の転送が多すぎます。いくつか完了するまで待つか、ペイロードを再起動してください。",
"joberr.zip_unsupported": "この .zip には、アップローダーがストリーミングできないもの（暗号化、Deflate または Stored 以外の圧縮方式、安全でない、または重複したファイルパス）が含まれています。パソコンで展開してから、フォルダーをアップロードしてください。",
"joberr.sevenz_unsupported": "この .7z は、アップローダーがストリーミングできない圧縮方式または機能を使っています。パソコンで展開してから、フォルダーをアップロードしてください。",
"joberr.sevenz_unsupported_layout": "この .7z は、1 つのソリッドブロック内でファイルの間にフォルダーまたは空のファイルが挟まっており、アップローダーがストリーミングできない構造です。7-Zip で再圧縮するか、展開してフォルダーをアップロードしてください。",
"joberr.rar_unsupported": "この .rar には、重複した、または安全でないファイルパス、あるいはアップローダーがストリーミングできない機能が含まれています。パソコンで展開してから、フォルダーをアップロードしてください。",
"pkg.patch_did_not_apply": "PS5 はこのアップデートを受け付けたものの、実際には何も行いませんでした。ゲームは以前のバージョンのままです。これは、インストール済みの本編とアップデートを結び付けられなかったことを意味します。このアップデートに対応する本編パッケージから ps5upload で本編を再インストールし（「上書き」を選択）、その後アップデートを適用し直してください。",
"pkglib.updateBaseUnknown.title": "このアップデートは適用されない可能性があります",
"pkglib.updateBaseUnknown.installAnyway": "それでもインストール",
"pkglib.updateBaseUnknown.body": "{id} はインストールされていますが、ps5upload が導入した本編パッケージからではありません。そのため PS5 がこのアップデートを結び付けられない可能性があります。その場合、本体は成功と報告しながら何も変更しません。あとでゲームが以前のバージョンのままなら、対応する本編パッケージを ps5upload でインストールし（「上書き」を選択）、アップデートを適用し直してください。",
"pkg.patch_regressed": "このアップデートを再適用したことで、逆に削除されました。ゲームは本編のバージョンに戻っています。PS5 のインストーラーは、再適用されたアップデートを「取り消すもの」として扱います。更新後のバージョンに戻すにはアップデートをもう一度適用し、すでに適用済みのアップデートを再インストールしないようにしてください。",
"sdk_patch_libc": "libc.prx も書き換える",
