"fpkg.about": "ゲームフォルダー、または .exfat／.ffpkg のマウントイメージを指定してください。コンバーターはツリーを読み取り、起動できるパッケージに必要なものがすべてそろっているか確認し、デバッグ形式の .pkg を出力フォルダーに書き込みます。",
"fpkg.aboutWhere": "変換は本体ではなく、エンジンを動かしているマシン（このコンピューター、Docker ホスト、Android 端末）で実行されます。パッケージをインストールするまで本体には何も届きません。インストールは、このコンピューターからのストリーム、または先に PS5 へアップロードする方法で行います。",
