connection_payload_engine_unreachable: "アプリがこのコンピューター上の自分のエンジンに接続できなかったため、ヘルパーが PS5 で起動したかどうかわかりません。PS5 の問題ではありません。ウィンドウ上部のお知らせに理由が表示され、エンジンを再起動できます。その後もう一度「ヘルパーを送信」を押してください。（{error}）",
"engine_problem.missing.fix": "ウイルス対策ソフトの隔離から ps5upload-engine を復元する（または許可する）か、アプリを再インストールしてください。",
