"profile.np.body": "Sony に接続することなく、サインイン中のアカウントを PlayStation Network にサインイン済みとして PS5 に扱わせます。本体の一部の機能はサインイン済みのアカウントにしか開かれず、リモートプレイもその一つです。earthonion の np-fake-signin を使い、ボタンを押したときにプロジェクトページから取得します。",
