"pkg.sony_80b21104": "PS5 がこのパッケージを受け付けませんでした (0x80B21104)。ほかのパッケージがこのゲーム機にインストールできるなら、原因はこのファイルです。多くは、このゲーム機のファームウェアが理解できるより新しいツールで作られた最近のゲームのパッケージか、偽署名 (FPKG) ビルドではないパッケージです。お使いのファームウェア向けのパッケージ (バックポート) を使うか、インストーラーを使わない方法で入れてください: ゲームフォルダー、または ShadowMount+ 用のゲームイメージ (.exfat か .ffpfsc) をアップロードでコピーします。",
