bringup_desc_v2: "ペイロードでプレイリストを設定したら、起動のたびに使えます：起動用プレイリスト（kstuff、ShadowMount+…）を実行し、手順 2 と同じ方法でヘルパーを送信してから、自動ローダーのプレイリストを実行します。",
changelog_description_v2: "このバージョンまでのすべての ps5upload バージョンのリリースノートで、アプリに同梱されています。より新しいリリースとそのダウンロードは GitHub にあります。",
