companion_suggest_open_payloads: "ペイロードを開く",
connection_first_run_nudge_body_v2: "セットアップウィザードは kstuff と ShadowMount+ をダウンロードして送信し、続けてヘルパーを正しい順序で送信します。本体がすでに kstuff を自分で読み込む場合（オートローダー、etaHEN）は、下の手順 2 でヘルパーだけを送信します。",
connection_step2_which: "ここではヘルパーだけを送信します。kstuff と ShadowMount+ も読み込むには、初回はセットアップウィザードを、プレイリストを設定した後は起動のたびに下のクイック起動を使ってください。",
