first_run_description_v3: "ほとんどの環境で必要なものを正しい順序で読み込みます：kstuff（フェイクパッケージのインストールと実行を可能にする）、ShadowMount+（ゲームイメージやフォルダーを PS5 のホーム画面に表示する）、そして ps5upload 自身のヘルパーです。PS5 の再起動後、接続画面でこのウィザードが再び提案されます。",
