hardware_description_v2: "ヘルパーが接続されている間、システム情報、稼働時間、ストレージは 5 秒ごとに自動更新されます。リアルタイムの温度と CPU クロックは必要なときに読み取ります — 「センサーを読み取る」をクリックしてください。製品版ファームウェアではすべての値が取得できるわけではなく（CPU 使用率など）、それらはダッシュで表示されます。",
