hw_fan_confirm_msg: "本体のファン制御がこの温度を保つように動作し、ps5upload はヘルパーが読み込まれるたびにこの値を設定し直します。低いほどうるさく、高いほど本体は高温で動作します。",
hw_fan_confirm_title: "ファンの目標温度を {c} °C に設定しますか？",
hw_kernel_log_link: "PS5 システムログ（カーネル）：ログ → カーネル を開く",
hw_sensor_no_reading: "本体はこのセンサーの値を返しませんでした",
keep_ps5_awake_mode_hint_v2: "PS5 の自動スタンバイタイマーを定期的にリセットし、レストモードに入らないようにします。「アップロードとインストール中」は長時間のアップロードを保護します（アップロード失敗のよくある原因です。既定）。「接続中は常に」は、アプリが開いている間、ヘルパーが動作しているすべての本体をレストモードに入らせません。どのモードでも、手動で PS5 をレストモードにすることはできます。",
kernellog_categories_explainer: "すべてのカテゴリーは最初は表示されています。Sony のカテゴリーは本体自身のサブシステムで、どのペイロードが動作していても、脱獄したすべての PS5 で常にログを出力します。ps5upload が原因ではありません。チェックを外すとノイズを減らせます。",
payloads_cached_body: "{kb} KB をローカルキャッシュにダウンロードしました。",
payloads_cached_title: "{id} {tag} をキャッシュしました",
payloads_description_catalog_v2: "厳選されたサードパーティ製の PS5 自作ペイロード。最新リリースを確認し、一度ダウンロードすれば、ワンクリックで PS5 に送信できます。バージョンはローカルにキャッシュされるので、USB ペイロードスティックに入れることもできます。",
payloads_description_send_v2: "任意の PS5 ペイロードファイル — .elf、.bin、.js、.lua、.jar（kstuff、自作ローダー、ブラウザー段階のエクスプロイト、プラグインスクリプト、BD-JB JAR）— を PS5 に送信します。接続画面と同じ流れで、選んだファイルを対象にします。ポートはファイルの種類で決まります（.elf/.bin 9021、.jar 9025、.lua 9026、.js 50000）。ローダーが別のポートで待ち受けている場合のみ変更してください。",
payloads_download_failed: "ダウンロードに失敗しました：{id}",
payloads_open_usb_wizard_v2: "USB ペイロードスティックを作成",
payloads_send_failed: "送信に失敗しました：{id}",
payloads_sent_body: "ペイロード v{version} を :9021 のローダーに送信しました。PS5 の通知を確認してください。",
payloads_sent_body_pm: "ポート 9021 が応答しなかったため、ペイロード v{version} は代わりに Payload Manager（:8084）経由で起動しました。PS5 の通知を確認してください。",
payloads_sent_title: "{id} を送信しました → {host}",
peripheral_drive_attachable: "このモデルにはディスクドライブが内蔵されていません。これらは外付けドライブを接続しているときにのみ機能します。",
power_telemetry_title_v2: "累計カウンター",
processes_kill_payload_body: "ペイロード「{name}」（kstuff、etaHEN など）を終了します。再度送信するまでその機能は停止し、それを必要とするゲームが起動しなくなる可能性があります。",
processes_kill_payload_title: "ペイロード「{name}」を停止しますか？",
"profile.np.browser_v2": "サインインにはデスクトップアプリが必要です：np-fake-signin を取得して PS5 に送信しますが、これは Web UI ではできません。",
ps5notif_empty_hint_v2: "ps5upload がテレビにメッセージ（リモートプレイの PIN やチートのオンなど）を表示すると、ここに一覧され、後から読み直せます。これは PS5 自身の通知パネルではありません。本体はそれを読み取らせてくれません。",
reset_confirm_body_browser: "このブラウザーが PS5Upload のために保存しているすべての設定と状態を消去し、ページを初期状態で再読み込みします。サーバー上のエンジン自身のデータ（本体のペアリング、コレクション、保存したサーバー、バックポート用ライブラリ、インストール履歴、ログ）には影響せず、PS5 上のものにも影響しません。元に戻すことはできません。",
reset_confirm_body_v2: "PS5Upload のローカルデータをすべて完全に削除します：設定、保存した PS5 とそのペアリング、コレクション、保存したサーバーとそのパスワード、バックポート用ライブラリ、インストール履歴、ジョブとイベント、アクティビティ / キューの履歴、ログ、ペイロードのキャッシュ、クラッシュレポート。PS5 上のものには一切触れません。アプリは初期状態で再読み込みされます。元に戻すことはできません。",
reset_hint_browser: "このブラウザーが PS5Upload のために保存しているすべての設定と状態を消去して、最初からやり直します。エンジンがサーバー上に保存しているもの（本体のペアリング、コレクション、保存したサーバー、バックポート用ライブラリ、インストール履歴、ログ）には影響せず、PS5 上のものにも影響しません。",
reset_hint_v2: "PS5Upload のローカルの痕跡をすべて消去して最初からやり直します：設定、保存した PS5 とそのペアリング、コレクション、保存したサーバーとそのパスワード、バックポート用ライブラリ、インストール履歴、ジョブとイベント、アクティビティ / キューの履歴、ログ、ペイロードのキャッシュ、クラッシュレポート。PS5 上のものには影響しません。上の「バックアップ / 復元」は、ペアリング、コレクション、サーバーのパスワード、バックポート用ライブラリを対象にしません。",
saves_backup_usb_tooltip_v2: "このセーブを、設定で指定したセーブのパス（PS5 の USB ドライブ）に zip で保存します。いったんこのコンピューターにコピーして zip にしてから送り返すので、アプリを開いたままにしてください。こちらのコピーは後で削除されます。",
saves_description_browser: "PS5 上のセーブデータ（ゲームごとに 1 項目）。セーブを .zip にバックアップしたり復元したりするにはデスクトップアプリが必要です。ここでは一覧の確認とフォルダーを開くことができます。",
saves_restore_usb_tooltip_v2: "設定で指定したセーブのパスにある最新のバックアップからこのセーブを復元します。zip をこのコンピューターにコピーして展開し、PS5 に送り返すので、アプリを開いたままにしてください。現在のセーブは上書きされます。",
saves_usb_menu: "USB",
saves_usb_menu_aria: "USB バックアップの操作",
