servers_subtitle: "NAS とサーバー（SMB、FTP、FTPS、SFTP/WebDAV）。ゲームやファイルを参照するどこからでも、「参照」の横の ▾ から選べます。",
settings_artwork_cache_explain_v2: "ゲームのカバー画像はエンジンが動作している場所（このコンピューター、Web 版ではサーバー）に保存され、毎回 PS5 から読み込む代わりにすぐに表示されます。自動で更新され、本体でゲームをインストールまたはアンインストールするとその本体の分は削除されます。",
settings_backup_downloaded: "{name} をダウンロードしました",
settings_backup_hint_v2: "テーマ、PS5 の一覧、通知履歴、アクティビティログなどの設定を 1 つの JSON ファイルにまとめ、アプリのストレージを消去した後や別のマシンで復元できます。本体のペアリング、コレクション、保存したサーバーのパスワード、バックポート用ライブラリは含まれません。",
settings_backup_restored: "{count} 件の設定を復元しました。すべての変更を反映するにはアプリを再起動してください。",
settings_backup_saved: "{path} に保存しました",
settings_card_console_rest: "レストモード",
settings_card_console_connect: "接続",
auto_bringup_label: "自動で起動する",
auto_bringup_hint: "保存済みのPS5でローダー(elfldr、ポート9021)が動いていてヘルパーが動いていないとき、アプリがクイック起動を自動で実行します: 設定していれば起動用プレイリスト、次にヘルパー、次に自動ローダーのプレイリストです。本体の起動ごとに1回だけで、レストモードの後はヘルパーだけを送り直します。本体側のオートローダーが先に終わるよう、ローダーが現れてから約90秒待ちます。初期設定はオフです。",
bringup_auto_hint_short: "PS5のローダーが動いていてヘルパーが動いていないとき、ローダーが現れてから約90秒後に自動で実行します。本体の起動ごとに1回です。",
settings_card_install_fallback: "PS5 がパッケージを取得できない場合",
settings_card_system_files: "システムファイル",
settings_file_hint_v2: "主な設定（テーマ、言語、エンジン、セーブのパス、アップロードの既定値、アクセシビリティ、サイドバー）はこの JSON ファイルにも反映されます。手で編集でき、次回アプリを起動したときに反映されます。すべてが含まれるわけではないので、設定をすべて移すには「バックアップ / 復元」を使ってください。",
settings_group_console: "本体",
settings_group_fakelibs: "バックポート",
settings_group_files_saves: "ファイルとセーブ",
settings_group_installs: "インストール",
settings_schedule_label_placeholder_v2: "ラベル（例：セーブをバックアップ）",
settings_updates_browser_note: "この Web ページは ps5upload エンジンが配信しており、エンジンと一緒に更新されます：新しい Docker イメージを取得して（またはサーバー上のエンジンを更新して）再起動してください。",
"show_file_list_hint_v2": "アップロード中のファイルを進行状況バーの下に一覧表示します。数千ファイルのフォルダーで一覧がうるさい場合はオフにしてください。全体の進行状況、速度、残り時間は引き続き表示されます。",
show_file_list_v2: "アップロード中にファイル一覧を表示",
stats_description_v2: "この本体について表示されている操作の合計です。アプリは最新の {count} 件を保持するため、それより古いものは数えられません。ローカルの履歴から計算され、何もこのマシンの外に出ません。",
status_keep_awake_tooltip_v2: "スリープ防止が「接続中は常に」に設定されています — アプリが開いている間、接続中の本体は自動でレストモードに入りません。設定 → 本体 で変更できます。",
update_idle_v2: "まだ確認していません。自動確認がオンの場合、アプリは起動時にバックグラウンドで確認します（1 日 1 回まで）。",
upload_auto_resume_hint_browser: "アップロードが転送途中で途切れた場合、PS5 のヘルパーが再び応答したら中断した位置から再開し、数回再試行してから諦めます。このページはヘルパー自体を再送信できないため、PS5 が再起動した場合は先にヘルパーを送信し直してください。PS5 の空き容量不足のような致命的な問題では、すぐに停止します。既定でオンです。",
upload_wake_for_uploads: "待機中のアップロードのために PS5 を起動",
upload_wake_for_uploads_hint: "レストモードの PS5 をアップロードが待っているとき、起動信号を送り、ヘルパーが戻りしだい続行します。接続画面で起動を設定したコンソールのみが対象です。既定でオン。",
upload_picker_from_ps5_hint: "別の PS5 からコピーしますか？ファイルシステムでファイルを選び、「別の本体に送信」を選んでください。",
