"rp_running_elsewhere_body": "別のウィンドウから、またはこのページの再読み込み前に開始され、まだ続いています。",
"rpg_user_title": "PS5 でユーザーにサインインする",
"rpg_user_body": "本体で、プレイに使うユーザーを選んでください。画面の前にいる必要はありませんが、ユーザーはサインインしている必要があります。ログインパスコードのないユーザーを使ってください。パスコードがあると、本体の起動時に自動サインインが止まります。",
"rpg_account_title": "そのユーザーにアカウント ID を付ける",
"rpg_account_body": "リモートプレイはアカウント ID でペアリングします。PlayStation Network に連携済みのユーザーにはすでにあります。オフラインのユーザーは、上の「ユーザー」で設定してください（どの ID でも動作します。控えておいてください。以後のセーブデータはその ID に結び付きます）。",
"rpg_signin_title": "アカウントを PlayStation Network にサインインさせる（オフライン）",
"rpg_signin_body": "PS5 は、サインイン済みのアカウントにしかリモートプレイを使わせません。本体のリモートプレイの設定がグレー表示なら、下のオフラインサインインを実行し（Sony には何も送信されません）、PS5 を再起動してください。元に戻すこともできます。",
"rpg_signin_fix": "サインインへ",
"rpg_service_title": "リモートプレイをオンにする",
"rpg_service_body": "設定 › システム › リモートプレイ › リモートプレイを有効にする。アプリがオンにすることもでき、ファームウェア 10.00 以降ではこのユーザーへの許可も行えます。 その後 開始 で「リモートプレイがオフ」と出る場合は、PS5 本体の設定でオンにしてください。有効なのは本体側のスイッチです。",
"rpg_rest_title": "PS5 をレストモードから起動できるようにする",
"rpg_rest_body": "設定 › システム › 省電力 › レストモード中に使う機能 で「インターネットに接続したままにする」と「ネットワーク経由でPS5の電源を入れられるようにする」をオンにしてください。これらがオフだと、レストモードの本体は起動できず、数秒後にネットワークもスリープします。これは本体でしか確認できません。",
"rpg_pair_title": "このアプリを本体とペアリングする",
"rpg_pair_body": "接続 › 起動してサインイン › 設定。ワンクリックでこのアプリを PS5 に登録し（PS Remote Play アプリのペアリングと同じです）、キーをこのコンピューターに保存します。ストリーミング、起動、サインインはすべてこのキーを使います。本体を初期化したり、ユーザーを変えたりした後はもう一度行ってください。",
"rpg_play_title": "プレイ",
"rpg_play_body": "リモートプレイを開いて「開始」を押します。本体がレストモードなら起動し、サインインしてストリーミングします。このコンピューターにつないだコントローラー、キーボード、またはタッチで遊べます。Sony の PS Remote Play アプリや chiaki-ng を使う場合は、下で PIN を発行してそちらに入力してください。",
"rpg_play_fix": "リモートプレイを開く",
"rpg_title": "リモートプレイの設定",
"rpg_progress": "確認済みの手順 {n} 件中 {done} 件完了",
"rpg_on_console": "本体で確認してください",
"rpg_trouble": "それでもうまくいかない場合",
"rpg_t_start_q": "プレイ画面でスタートがグレーになっている。",
"rpg_t_start_a": "このアプリはまだその本体とペアリングされていません。手順 6（接続 › 起動してサインイン › 設定）を行ってください。",
"rpg_t_pair_q": "ペアリングの設定で、有効化されたアカウントでサインインしているユーザーがいないと表示される。",
"rpg_t_pair_a": "手順 1 と 2：PS5 でユーザーにサインインしてアカウント ID を付けてから、もう一度お試しください。",
"rpg_t_grey_q": "PS5 本体のリモートプレイの設定がグレー表示になっている。",
"rpg_t_grey_a": "アカウントが PlayStation Network にサインインしていません。オフラインサインイン（手順 3）を実行し、PS5 を再起動してください。",
"rpg_t_wake_q": "本体が起動しない、または起動してもユーザー選択画面のままになる。",
"rpg_t_wake_a": "本体で手順 5 を確認してください。ログインパスコードのあるユーザーでは自動サインインが止まります。本体を初期化したりユーザーを変えたりした場合は、ペアリングをもう一度設定してください（手順 6）。",
"rpg_t_black_q": "映像が黒いまま、カクつく、または音が途切れる。",
"rpg_t_black_a": "PS5 とこのコンピューターは有線接続か 5 GHz Wi-Fi にして、リモートプレイの設定で 720p や 30 fps を試してください。このコンピューターのファイアウォールで、ローカルネットワーク上のアプリを許可する必要があります（リモートプレイは TCP と UDP のポート 9295–9304 を使います）。ブラウザーでは最新の Chrome、Edge、Safari を使ってください。映像の表示には WebCodecs が必要です。",
"rpg_t_busy_q": "PS5 が前回のセッションをまだ終了中、または別の本体がストリーミング中と表示される。",
"rpg_t_busy_a": "ストリーミングできるのは一度に1台で、セッション終了後の PS5 には最大 30 秒かかります。もう一方のストリームを停止し、少し待ってから、もう一度「開始」を押してください。",
"rpg_t_restrict_q": "オフラインサインインの後、ゲームが本体の利用制限の解除を求めてくる。",
"rpg_t_restrict_a": "このページの「サインインを元に戻す」を使って再起動するか、設定 › ファミリーとペアレンタルコントロール › PS5 本体の利用制限 で制限を解除してください（変更していなければパスコードは 0000）。",
