"send_title_v2": "アップロード＆インストール",
"collection.send_many_body_v2": "各 PS5 には足りないものが届きます。ゲームのパッケージ、またはフォルダー・イメージ・アーカイブ、そして持っているゲームの新しいアップデートと DLC です。パッケージはこのコンピューターからストリーミングされ、それ以外は「アップロード＆インストール」で設定したドライブの homebrew フォルダーにアップロードされます。",
"first_run_step4_body_v3": ".ffpkg ゲームイメージの入った USB メモリを PS5 に挿すと、ShadowMount+ が自動でマウントし、ゲームに表示されます。ほかのファイルを送ったり .pkg パッケージをインストールしたりするには「アップロード＆インストール」を使ってください。",
"first_run_go_upload_v2": "「アップロード＆インストール」を開く",
"fpkg.aboutFake_v2": "結果はフェイクパッケージなので、インストール前に本体でフェイクパッケージ対応を読み込んでおく必要があります：kstuff（PS5 フェイクパッケージ対応のビルド）、a53_ppr_install_fast.elf、shadowmountplus.elf をこの順番で。「アップロード＆インストール」でも、インストールボタンの横に同じことが書かれています。",
"fpkg.openUpload_v2": "「アップロード＆インストール」を開く",
"connection_step3_hint_v3": "「アップロード＆インストール」を開き、ゲームフォルダー、.exfat や .ffpkg のイメージ、または .pkg パッケージをドロップしてください。送ったイメージとフォルダーは「ゲーム」のそのゲームのページに表示され、「マウント」で PS5 のホーム画面に表示されます。",
"connection_go_upload_v2": "「アップロード＆インストール」を開く",
"netdoctor.speed_cap.on.fix_v2": "不要なら「アップロード＆インストール」で制限を外してください。",
"payloads_fpkg_ppr_note_v2": "フェイクパッケージのインストールには、この一覧にない a53_ppr_install_fast.elf も必要です。配布されたダウンロードはなく、GitHub のソースからビルドします。フェイクパッケージに必要なものは「アップロード＆インストール」に順番どおり載っています。",
"fs_extract_next_pkgs_v2": "パッケージが {n} 個入っています。「アップロード＆インストール」か、ここにある各行からインストールしてください。",
"game_hub_no_addons_v2": "このタイトル用の DLC パッケージは配置されていません。「アップロード＆インストール」から送ってください。",
"game_hub_open_install_v2": "「アップロード＆インストール」を開く",
"bandwidth_cap_off_hint_v3": "制限なし。アップロードで Wi-Fi/LAN が埋まり、ほかの機器が遅くなる場合は設定してください。次に始まるものから、「アップロード＆インストール」、キュー、ファイルからのすべてのアップロードに適用されます。",
"queue_links_cleared_body_v2": "再起動後、{n} 件のインストールリンクは保持されませんでした。リンクはディスクに保存されません。「アップロード＆インストール」から追加し直してください。",
"game_hub_no_updates_v2": "このタイトル用のアップデートパッケージは配置されていません。「アップロード＆インストール」から送ってください。",
"pkglib.fpkgsupport.firmware": "PS5 のフェイクパッケージ（PS5 FPKG）は、11.60 より新しいファームウェアではまだ対応していません。インストールはできますが、ゲームは起動しません。PS4 のフェイクパッケージは問題ありません。",
"upload_drop_here3": "パッケージ、ゲーム、ディスクイメージ、アーカイブ、または任意のファイルをドロップまたは選択",
"upload_pick_here_mobile3": "パッケージ、ゲーム、ディスクイメージ、アーカイブ、または任意のファイルを選択",
"upload_drop_kind_pkg": "パッケージ（.pkg、.fpkg）：ゲーム、アップデート、DLC としてインストールされます。ここからストリーム、または先にアップロードします。",
"upload_drop_kind_game": "ゲームフォルダーとゲームのダンプ：PS5 にコピーされ、ホーム画面に置けます。",
"upload_drop_kind_image": "ディスクイメージ（.exfat、.ffpkg、.ffpfs、.ffpfsc）：PS5 にコピーされ、マウントできます。",
"upload_drop_kind_archive": "アーカイブ（.zip、.7z、.rar）：PS5 上に展開されます。",
"upload_drop_kind_other": "その他のファイルやフォルダー：そのままコピーされます。",
"upload_other_ways": "またはパッケージをインストール：",
"queue_stream_fail_hint": "「ストリーム＆インストール」では、PS5 がこのコンピューターからパッケージを取得します。失敗が続く場合は、PS5 から接続できるよう、このコンピューターのファイアウォールでローカルネットワーク上の ps5upload を許可するか、「アップロードして再試行」を使ってください。こちらはパッケージを先に PS5 にコピーしてからインストールします。",
"err_install_enoent_generic_v2": "Sony のインストーラーがインストール中に必要なファイルを開けませんでした（カーネルエラー 0x80020002 = ENOENT）。DLC の pkg なら、ベースゲームがまだインストールされていません。先にベースゲームをインストールしてください。それ以外の場合は、ステージングしたパッケージがアップロードとインストールの間に削除された可能性があります。インストールを一度再試行してください。それでも失敗が続く場合は、「アップロード＆インストール」の「ストリーム＆インストール」でインストールしてください。パッケージを本体に先にコピーせず、このコンピューターから直接送ります。",
"upload_convert_first": "先に変換",
"batch_convert_first_hint": "チェックしたゲーム、フォルダー、イメージをワークショップで開き、先にパッケージ、イメージ、フォルダーにします",
"add_sources_pick_folders": "フォルダーを 1 つ以上選択",
"add_sources_pick_files": "ファイルを 1 つ以上選択",
"workshop_add_locked": "ゲームを作成中です。今選んだゲームはキューで待機します。",
"workshop_add_hint": "ゲームを 1 本選ぶと、ここで確認できます。複数のゲームやゲームのフォルダーはキューに入り、順番に作成されます。",
"workshop_description_v2": "PS5 に送る前にゲームの形式を変えます。パッケージ（.pkg）、ゲームイメージ（.exfat、.ffpkg、より小さい .ffpfsc）、または通常のフォルダーを作成したり、イメージやパッケージの中身を見てファイルを変更したりできます。処理はこのコンピューターで行われます。ゲームをそのまま送るには「{send}」を使ってください。",
"cq_title_v2": "⑤ キュー",
"cq_about": "このコンピューターで順番に作成され、それぞれ追加した時点の ②、③、④ の設定が使われます。キューの実行中でも ① から追加できます。待機中のゲームはオプションボタンで変更できます。",
"cq_then_send": "インストールまたはアップロードに設定したゲームは、作成後に「{send}」のキューへ送られます。",
"cq_open_send": "「{send}」を開く",
