"collection.empty_body_v2": "中にあるパッケージ、ゲームフォルダー、ゲームイメージ、アーカイブを見つけて、ゲームごとにまとめます。フォルダー内は何も変更しません。このデバイスのフォルダー、外付けドライブ、NAS やサーバー（SMB、FTP、SFTP、WebDAV）のフォルダーのどれでも使えます。",
